import type { Href } from "expo-router";

// Technician app routes. The (tech) group uses its own URL names (open-jobs,
// my-jobs, scan, profile, tech-job/[id]) so nothing collides with the
// homeowner app's "/" index or its /job/[id] screen.
//
// Cast to Href because .expo/types/router.d.ts (typed routes) is only
// regenerated by `expo start`, so new routes aren't in it until then.
export const TECH_HOME = "/open-jobs" as Href;
export const TECH_MY_JOBS = "/my-jobs" as Href;
export const TECH_SCAN = "/scan" as Href;
export const TECH_PROFILE = "/profile" as Href;
export const HOMEOWNER_HOME = "/" as Href;
export const TECHNICIAN_ACCESS = "/technician-access" as Href;

export function techJobHref(jobId: string): Href {
  return `/tech-job/${encodeURIComponent(jobId)}` as Href;
}

/** Top-level route segments that belong to the technician app. */
export const TECH_GROUP = "(tech)";
/** Top-level route segment of the homeowner tab app. */
export const HOMEOWNER_TABS_GROUP = "(tabs)";
